# Complete machine-readable canonical ERD source, partitioned for readability.
def mermaid(names):
 s=['erDiagram']
 for n in names:
  s.append('  '+n+' {')
  s.append('    uuid id PK')
  for f,t in entities[n]['fields']:
   typ=re.sub(r'[^A-Za-z0-9_]','_',t)
   key=' FK' if (t=='uuid' and (f.endswith('Id') or f.endswith('_id') or f in ('suborderId','suborder_id'))) else ''
   s.append('    '+typ+' '+f+key)
  s.append('  }')
 for r in relations:
  if r['from'] in names and r['to'] in names:
   parent,child=r['to'],r['from']
   left='|o' if r['optional'] else '||'
   right='o|' if r['cardinality']=='1:1' else 'o{'
   s.append(f'  {parent} {left}--{right} {child} : "{r["field"]}"')
 return '\n'.join(s)
